class SubmitLoanRequestModule_AutoGenerated {
  /*find a loan request with provided request id, if the loan request is not exist, create a new loan request with provided info and save it, then the current loan request is it*/
  enterLoanInformation(
    requestid: number,
    name: string,
    loanamount: number,
    loanpurpose: string,
    income: number,
    phonenumber: number,
    postaladdress: string,
    zipcode: number,
    email: string,
    workreferences: string,
    creditreferences: string,
    checkingaccountnumber: number,
    securitynumber: number,
  ): boolean {
    /*Definition Start*/
    let loanRequest: LoanRequest = l({
      logic: () =>
        getRepository(LoanRequest).find(
          (lr: any) =>
            l({
              logic: () => lr.RequestID === requestid,
              description: "lr.RequestID=requestid",
            }).build().pass,
        ),
      description: "LoanRequest.allInstance()->any(lr|lr.RequestID=requestid)",
    }).build().pass;
    let notExist: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(loanRequest),
      description: "loanRequest.oclIsUndefined()",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(requestid, Integer),
        description: "requestid.oclIsTypeOf(Integer)",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(name, String),
          description: "name.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(loanamount, Real),
          description: "loanamount.oclIsTypeOf(Real)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(loanpurpose, String),
          description: "loanpurpose.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(income, Real),
          description: "income.oclIsTypeOf(Real)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(phonenumber, Integer),
          description: "phonenumber.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(postaladdress, String),
          description: "postaladdress.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(zipcode, Integer),
          description: "zipcode.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(email, String),
          description: "email.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(workreferences, String),
          description: "workreferences.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(creditreferences, String),
          description: "creditreferences.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(checkingaccountnumber, Integer),
          description: "checkingaccountnumber.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(securitynumber, Integer),
          description: "securitynumber.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => notExist,
          description: "notExist",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newLoanRequest: LoanRequest;
    return l({
      execute: () => (newLoanRequest = new LoanRequest()),
      description: "newLoanRequest.oclIsNew()",
    })
      .and({
        execute: () => getRepository(LoanRequest).push(newLoanRequest),
        description: "LoanRequest.allInstance()->includes(newLoanRequest)",
      })
      .and({
        execute: () => (newLoanRequest.RequestID = requestid),
        description: "newLoanRequest.RequestID=requestid",
      })
      .and({
        execute: () => (newLoanRequest.Name = name),
        description: "newLoanRequest.Name=name",
      })
      .and({
        execute: () => (newLoanRequest.LoanAmount = loanamount),
        description: "newLoanRequest.LoanAmount=loanamount",
      })
      .and({
        execute: () => (newLoanRequest.LoanPurpose = loanpurpose),
        description: "newLoanRequest.LoanPurpose=loanpurpose",
      })
      .and({
        execute: () => (newLoanRequest.Income = income),
        description: "newLoanRequest.Income=income",
      })
      .and({
        execute: () => (newLoanRequest.PhoneNumber = phonenumber),
        description: "newLoanRequest.PhoneNumber=phonenumber",
      })
      .and({
        execute: () => (newLoanRequest.PostalAddress = postaladdress),
        description: "newLoanRequest.PostalAddress=postaladdress",
      })
      .and({
        execute: () => (newLoanRequest.ZipCode = zipcode),
        description: "newLoanRequest.ZipCode=zipcode",
      })
      .and({
        execute: () => (newLoanRequest.Email = email),
        description: "newLoanRequest.Email=email",
      })
      .and({
        execute: () => (newLoanRequest.WorkReferences = workreferences),
        description: "newLoanRequest.WorkReferences=workreferences",
      })
      .and({
        execute: () => (newLoanRequest.CreditReferences = creditreferences),
        description: "newLoanRequest.CreditReferences=creditreferences",
      })
      .and({
        execute: () =>
          (newLoanRequest.CheckingAccountNumber = checkingaccountnumber),
        description:
          "newLoanRequest.CheckingAccountNumber=checkingaccountnumber",
      })
      .and({
        execute: () => (newLoanRequest.SecurityNumber = securitynumber),
        description: "newLoanRequest.SecurityNumber=securitynumber",
      })
      .and({
        execute: () => (newLoanRequest.Status = LoanRequestStatus.SUBMITTED),
        description: "newLoanRequest.Status=LoanRequestStatus::SUBMITTED",
      })
      .and({
        execute: () => (this.CurrentLoanRequest = newLoanRequest),
        description: "self.CurrentLoanRequest=newLoanRequest",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
